def remove_tz(date_time: str) -> str:
    dt = datetime.fromisoformat(date_time)
    if dt.tzinfo is not None and dt.utcoffset() is not None:
        dt = dt.astimezone(UTC)
    dt = dt.replace(tzinfo=None)
    return dt.isoformat()


